// Restaurant analytics and ROI.
// Owner: Agent B2 (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
//
// Every analytics response carries `meta: AnalyticsMeta` describing how the
// numbers were computed, which assumptions (if any) were used, and how much of
// the data could be used. Measured results are deterministic SQL over tenant
// data. Hypothetical results (ROI calculator) are `kind: 'hypothetical'`.
import { z } from 'zod';
import { isoDate, uuid } from './common';

export const analyticsContractsVersion = 1 as const;

export const MAX_ANALYTICS_DAYS = 400;

export const analyticsPeriodQuery = z.object({
  /** Inclusive local dates in the branch (or organization) timezone. */
  from: isoDate,
  to: isoDate,
  branchId: uuid.optional(),
  /** previous: the same number of days just before; last_year: the same local dates one year earlier (21-INSIGHTS). */
  compare: z.enum(['previous', 'last_year', 'none']).default('previous'),
}).refine((q) => q.from <= q.to, { message: 'from must not be after to', path: ['to'] })
  .refine((q) => (Date.parse(q.to) - Date.parse(q.from)) / 86_400_000 < MAX_ANALYTICS_DAYS, { message: `at most ${MAX_ANALYTICS_DAYS} days`, path: ['from'] });
export type AnalyticsPeriodQuery = z.infer<typeof analyticsPeriodQuery>;

export const paperIndicatorQuery = z.object({
  from: isoDate,
  to: isoDate,
  branchId: uuid.optional(),
  /** Optional caller assumption: grams of paper per avoided printed sheet. Without it no weight is reported. */
  gramsPerSheet: z.coerce.number().positive().max(100).optional(),
}).refine((q) => q.from <= q.to, { message: 'from must not be after to', path: ['to'] });

const percent = z.number().min(0).max(100).refine((n) => Math.abs(Math.round(n * 100) - n * 100) < 1e-6, 'at most 2 decimals');

/**
 * ROI calculator assumptions. Everything the result depends on is listed here and
 * echoed back. If baselineMonthlyNetRevenueMinor is omitted, the measured average
 * of the last `baselineDays` days (ex-VAT, net of refunds) is used and labelled.
 */
export const roiInput = z.object({
  branchId: uuid.optional(),
  baselineMonthlyNetRevenueMinor: z.number().int().min(0).max(1e13).optional(),
  baselineDays: z.number().int().min(7).max(365).default(90),
  expectedUpliftPct: percent,
  /** Ingredient (food) cost as % of revenue. If omitted, the measured cost ratio is used when cost coverage ≥ 80%. */
  ingredientCostPct: percent.optional(),
  /** Other variable costs on extra revenue (payment fees, packaging, delivery commissions), % of revenue. */
  variableCostPct: percent.default(0),
  subscriptionMonthlyCostMinor: z.number().int().min(0).max(1e11),
  otherMonthlyCostMinor: z.number().int().min(0).max(1e11).default(0),
  oneTimeSetupCostMinor: z.number().int().min(0).max(1e11).default(0),
  months: z.number().int().min(1).max(36).default(12),
});
export type RoiInput = z.infer<typeof roiInput>;

export interface AnalyticsMeta {
  /** Plain-language description of how the numbers were computed. */
  method: string;
  /** Assumptions applied. Empty for purely measured results. */
  assumptions: Array<{ key: string; value: string | number | boolean; source: 'caller' | 'measured' | 'default' }>;
  dataCoverage: Record<string, number | string | boolean | null>;
  kind: 'measured' | 'hypothetical' | 'mixed';
  timezone: string;
  generatedAt: string;
}

export interface RevenueTotals {
  orders: number;
  cancelledOrders: number;
  grossMinor: number;          // before discounts: total + discounts
  discountsMinor: number;
  refundsMinor: number;
  netMinor: number;            // total billed − refunds (VAT inclusive)
  vatMinor: number;            // VAT on non-cancelled orders
  netExVatMinor: number;       // netMinor − vatMinor
  deliveryFeesMinor: number;
  serviceChargeMinor: number;
  paidMinor: number;
  averageOrderMinor: number;   // round(total billed / orders)
}
